import unicodedata

def slugify(s):
    s = s.lower()
    # Normalize Unicode characters to ASCII
    s = unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('ascii')
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            if not out or out[-1] != '-':
                out.append('-')
    # Strip leading and trailing dashes
    result = ''.join(out).strip('-')
    return result

import unicodedata

def slugify(s):
    s = s.lower()
    # Normalize unicode characters (e.g., 'õ' -> 'o' + combining mark)
    s = unicodedata.normalize('NFKD', s)
    # Remove combining characters (diacritics)
    s = ''.join(c for c in s if not unicodedata.combining(c))

    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')

    # Collapse multiple '-' into single '-'
    result = []
    prev = None
    for ch in out:
        if ch == '-' and prev == '-':
            continue
        result.append(ch)
        prev = ch

    return ''.join(result).strip('-')
